const processMap: GuideCourse = {
  id:'process-map', task:'task1', name:'流程 / 地图', en:'Process & Map', accent:'#cbbcff',
  promise:'流程题讲清阶段与转化，地图题讲清方位与功能变化。', duration:'20 MIN', targetWords:'170–200 WORDS',
  coreRule:'两类题都没有传统数据比较，但逻辑不同：流程题按阶段和物质变化组织，多用被动语态；地图题按空间区域和前后变化组织，多用改建、扩建与保留表达。',
  questionSignals:['The diagram shows how … is produced / recycled.','The process illustrates the stages involved in …','The maps show [place] before and after …','The plans compare the layout of … in [years].'],
  examFlow:[{time:'00–02',action:'先判流程或地图',output:'流程找起终点/阶段；地图找方向/基准物/年份。'},{time:'02–04',action:'划分两组',output:'流程分前后阶段；地图按功能区或方位分区。'},{time:'04–17',action:'按顺序成文',output:'Overview 写总体转化；细节保持时间或空间路线。'},{time:'17–20',action:'动词检查',output:'流程查被动与顺序；地图查方位、变化动词和时态。'}],
  blueprint:[{part:'P1 · Introduction',words:'25–35',job:'改写生产过程或地点/平面图变化。'},{part:'P2 · Overview',words:'35–45',job:'流程写类型、起终点和阶段；地图写总体功能转向与主要保留。'},{part:'P3 · Details 1',words:'55–65',job:'流程写前半阶段；地图写北/西/核心区或早期主要变化。'},{part:'P4 · Details 2',words:'55–65',job:'流程写后半阶段；地图写其余区域并完成前后关系。'}],
  paragraphs:[
    {label:'PARAGRAPH 01',title:'开头段：先让考官知道你面对哪一种图',purpose:'准确改写流程对象或地图地点、时间，不添加图外用途。',words:'25–35 words',formula:'Diagram/map type ＋ Subject/place ＋ Time/purpose',steps:['流程题找 produce / recycle / life cycle 的核心对象。','地图题找地点、两个时间点和 proposal / redevelopment。','保持客观，不解释为什么改造或哪个方案更好。'],sentenceFrames:['The diagram illustrates the process by which [product] is manufactured.','The figure shows the stages involved in recycling …','The maps compare the layout of [place] in [year] and at present.','The plans show how [site] is proposed to be redeveloped.'],wordBank:['manufacture 制造','stages involved in 涉及阶段','layout 布局','redevelop 重新开发','proposed 规划中的','life cycle 生命周期'],example:'The diagrams illustrate how cement is manufactured from raw materials and how the finished cement is subsequently used in the production of concrete.',coachNote:'process 用 how … is produced；map 用 how a place changed。二者句法不要混用。'},
    {label:'PARAGRAPH 02',title:'Overview：流程看转化，地图看功能',purpose:'不写细枝末节，概括全图的起终点、阶段结构或整体空间变化。',words:'35–45 words',formula:'Process: linear/cyclical + start/end + major phases · Map: overall transformation + additions/removals + retained feature',steps:['流程先判断线性、循环、自然或人工过程。','找原料输入、成品输出和关键转化点。','地图判断总体从住宅/农业转向旅游/商业等功能。','指出最大新增、拆除以及重要保留。'],sentenceFrames:['Overall, this is a linear, [number]-stage process beginning with … and ending with …','The cycle is continuous, as the final stage leads back to …','Overall, the area became more residential / accessible / recreational.','Most of the site was redeveloped, while [feature] remained intact.'],wordBank:['linear 线性的','cyclical 循环的','culminate in 最终于','undergo redevelopment 经历改造','remain intact 保持不变','be transformed into 被转变为'],example:'Overall, cement production is a linear process involving crushing, mixing, heating and grinding, whereas concrete is created in a single mixing stage from four ingredients. The finished cement forms only one component of the final concrete mixture.',coachNote:'Overview 不是重复图题。流程要写“从什么到什么”，地图要写“从何种功能变成何种功能”。'},
    {label:'PARAGRAPH 03',title:'细节段一：建立一条不会迷路的描述路线',purpose:'按前半流程或固定方位写第一组信息，保持顺序连续。',words:'55–65 words',formula:'Start point/location → Sequential changes → Intermediate stage / spatial comparison',steps:['流程用 first / once / following this 推进，并写物质状态变化。','地图先选北到南、左到右或核心到外围的一条路线。','每句让旧物与新物发生对应：was replaced by / converted into。','不要在描述中跳回已经写过的区域。'],sentenceFrames:['Initially, [materials] are fed into …','Once crushed, the material is transferred to …','In the northern part of the site, the former X was replaced by Y.','To the west of [landmark], a new … was constructed.'],wordBank:['be fed into 被送入','be transferred to 被转移到','undergo 经历','be replaced by 被取代','be converted into 被改建为','to the north of 位于…北侧'],example:'Initially, limestone and clay are passed through a crusher to form powder. This material is then mixed before entering a rotating heater, where heat is applied from one end. The heated mixture subsequently travels along a conveyor to a grinder, producing fine cement.',coachNote:'地图方位必须相对于明确基准物；流程中的 it / this material 必须让读者知道指什么。'},
    {label:'PARAGRAPH 04',title:'细节段二：完成后半阶段或剩余区域并闭环',purpose:'描述流程输出、循环返回或地图另一功能区，确保全图覆盖。',words:'55–65 words',formula:'Intermediate point → Remaining changes → Final output / retained relationship',steps:['流程继续沿箭头到最终产品，写输入比例时保持准确。','循环流程说明末端如何回到开头。','地图覆盖剩余区域，并补充道路、入口、路径等连接变化。','最后一句可对照保留项，但不写个人评价。'],sentenceFrames:['At the final stage, the material is … before being packaged.','The resulting product is then combined with … in a mixer.','Meanwhile, the southern section was converted into …','Although X was expanded, Y remained in its original position.'],wordBank:['resulting product 所得产品','be combined with 与…混合','be packaged 被包装','meanwhile 与此同时','be expanded 被扩建','retain 保留'],example:'After grinding, the cement is packaged for distribution. To produce concrete, 15% cement is added to 10% water, 25% sand and 50% gravel. These ingredients are poured into a concrete mixer, which rotates until the four materials form the finished product.',coachNote:'流程结尾要真正到达输出；地图结尾要覆盖另一半空间。不要停在中间阶段。'},
  ],
  languageZones:[{title:'流程顺序',note:'让步骤自然衔接。',items:['initially / at the outset','once this has occurred …','following this stage …','the process culminates in …']},{title:'流程被动',note:'关注动作而非执行者。',items:['be crushed / heated / filtered','be fed into / passed through','undergo treatment','be combined with …']},{title:'地图变化',note:'精准区分新增与转换。',items:['be constructed / added','be demolished / removed','be replaced by / converted into','be expanded / relocated']},{title:'方位与保留',note:'建立空间关系。',items:['to the north / south of …','in the north-eastern corner','adjacent to / opposite …','remain intact / unchanged']}],
  scoreFocus:task1ScoreFocus,
  pitfalls:['流程遗漏起点、输出或循环返回。','流程只用主动语态且主语反复是 people。','地图没有固定路线，东跳西跳。','把 replaced by 的前后对象写反。','加入图中没有的原因、好处或推测。','Overview 只说有很多变化。'],
  checklist:['我是否先判断了流程/地图的组织逻辑？','Overview 是否有起终点或总体功能变化？','流程是否覆盖所有关键阶段且顺序正确？','地图是否使用明确方位和基准物？','被动语态、变化动词和时态是否准确？','是否避免了所有图外解释和评价？'],
  drills:['为任一流程只写“起点—转化—终点”Overview。','用被动语态连续描述五个制造动作。','选择地图固定路线，用 45 秒口述全部变化。','分别练 added / replaced / converted / retained 四类地图句。'],
};

export const guideCourses: GuideCourse[] = [opinion, discussion, advantages, problem, twoPart, line, bar, pie, table, processMap];

export function getGuideCourse(id: string) {
  return guideCourses.find(course=>course.id===id);
}
